// ABOUTME: Builds policy conditions from stored request contexts.
// ABOUTME: Used by approvalsapi's "allow exact request" and "allow domain" instant policy flows.

import type { Condition } from "@zapier/policy-schema";
import type {
  HttpRequestContext,
  ActionRunContext,
  ActionType,
} from "./types.ts";
import { IGNORED_HEADERS } from "./constants.ts";

/**
 * Build conditions that match an exact HTTP request.
 *
 * Handles the matches_url / query param split correctly:
 * - `matches_url` only supports scheme+host+port+path (no query string per spec)
 * - Query parameters are added as separate decomposed conditions on `url.query.<key>`
 *
 * @returns Condition[] for an http permission statement
 */
export function buildExactHttpConditions(
  context: HttpRequestContext,
): Condition[] {
  const conditions: Condition[] = [
    { path: ["method"], operator: "equals", value: context.method },
  ];

  const { url } = context;

  // matches_url condition uses URL without query string (per @zapier/policy spec)
  const defaultPort =
    url.scheme === "https" ? 443 : url.scheme === "http" ? 80 : 0;
  const portString = url.port !== defaultPort ? `:${String(url.port)}` : "";
  const urlWithoutQuery = `${url.scheme}://${url.host}${portString}${url.path}`;
  conditions.push({
    path: ["url"],
    operator: "matches_url",
    value: urlWithoutQuery,
  });

  // Add decomposed conditions for each query parameter.
  for (const [key, values] of Object.entries(url.query)) {
    conditions.push({
      path: ["url", "query", key],
      operator: "equals",
      value: values,
    });
  }

  // body_json condition
  if (context.body_json !== null) {
    conditions.push({
      path: ["body_json"],
      operator: "equals",
      value: context.body_json,
    });
  } else if (context.body !== null) {
    // Non-JSON body (text/plain, XML, form-encoded): pin the raw body so
    // exact-match policies actually match the originating request.
    conditions.push({
      path: ["body"],
      operator: "equals",
      value: context.body,
    });
  }

  // Header conditions (filtered through IGNORED_HEADERS again for safety)
  for (const [key, value] of Object.entries(context.headers)) {
    if (!IGNORED_HEADERS.has(key.toLowerCase()) && typeof value === "string") {
      conditions.push({
        path: ["headers", key.toLowerCase()],
        operator: "equals",
        value,
      });
    }
  }

  return conditions;
}

/**
 * Build conditions that match any request to a given domain.
 * Uses the host from the parsed URL.
 *
 * @returns Condition[] for an http permission statement
 */
export function buildDomainHttpConditions(
  context: HttpRequestContext,
): Condition[] {
  return [
    {
      path: ["url", "host"],
      operator: "matches_host",
      value: context.url.host,
    },
  ];
}

/**
 * Build conditions that match an exact action run (with inputs).
 *
 * @returns Condition[] for an action permission statement
 */
export function buildExactActionConditions(
  context: ActionRunContext,
): Condition[] {
  const conditions: Condition[] = [];

  if (context.inputs !== undefined && context.inputs !== null) {
    conditions.push({
      path: ["inputs"],
      operator: "equals",
      value: context.inputs,
    });
  }

  return conditions;
}

/**
 * The three identity fields that compose an action resource string.
 */
export interface ActionResourceParts {
  selected_api: string;
  action_type: ActionType;
  action_key: string;
}

/**
 * Build the resource string for an action.
 * Format: action/{selected_api}/{action_type}/{action_key}
 */
export function buildActionResource(parts: ActionResourceParts): string {
  return `action/${parts.selected_api}/${parts.action_type}/${parts.action_key}`;
}

/**
 * Build a broad action resource that matches all actions of the same type
 * for an app (e.g. all reads, all writes). Scopes on `action_type` to
 * avoid silently granting cross-type access.
 *
 * Format: action/{selected_api}/{action_type}/{wildcard}
 */
export function buildBroadActionResource(
  parts: Pick<ActionResourceParts, "selected_api" | "action_type">,
): string {
  return `action/${parts.selected_api}/${parts.action_type}/*`;
}
