// ABOUTME: Builds connection-level policies for the basic approvals MVP.
// ABOUTME: Generates deterministic policies that allow read or read+write access scoped to a specific connection.

import { z } from "zod";
import type { Policy, Statement, Condition } from "@zapier/policy-schema";
import {
  parseActionResource,
  type ActionType,
  type RequestContext,
} from "./types.ts";

/**
 * Replace the implementation-version suffix of a `selected_api` with a `@*`
 * wildcard so connection-level policies stay valid across version bumps. A
 * runtime request with `selected_api: "App@2.7.3"` matches a policy resource
 * scoped to `App@*` while still being distinguishable from a different app
 * (e.g. `App2@1.0.0`).
 *
 * No-op when the input has no `@` — assumed to be already version-less.
 */
function globSelectedApiVersion(selectedApi: string): string {
  const at = selectedApi.indexOf("@");
  return at === -1 ? selectedApi : selectedApi.slice(0, at) + "@*";
}

export const AccessLevelSchema = z.enum(["read", "read_write"]);
export type AccessLevel = z.infer<typeof AccessLevelSchema>;

/** HTTP methods that count as side-effect-free reads for connection-level policies. */
export const READ_HTTP_METHODS = ["GET", "HEAD", "OPTIONS"] as const;

/**
 * Action types that count as side-effect-free reads for connection-level
 * policies. `read_bulk` is the paginated/bulk variant of `read` — same
 * external API semantics, no mutations. Widely used by major apps (Slack,
 * Gmail, Jira, Salesforce, etc.) via the public `bulkReads` schema key.
 * `filter` and `run` are excluded: neither has a runtime executor for
 * external apps, and `filter` actions don't carry a connection_id anyway,
 * so this allowlist has no effect on them.
 */
export const READ_ACTION_TYPES = [
  "read",
  "read_bulk",
  "search",
] as const satisfies readonly ActionType[];

const READ_HTTP_METHOD_SET: ReadonlySet<string> = new Set(READ_HTTP_METHODS);
const READ_ACTION_TYPE_SET: ReadonlySet<ActionType> = new Set(
  READ_ACTION_TYPES,
);

/**
 * Returns true when the request needs write access (i.e. it is NOT a
 * side-effect-free read). Mirrors the logic encoded in `buildConnectionPolicy`
 * so UI surfaces that gate the read-vs-read_write choice stay consistent
 * with the policies they generate.
 */
export function isWriteRequest(context: RequestContext): boolean {
  if (context.request_type === "http_request") {
    // Method is uppercase by construction (buildHttpRequestContext canonicalizes
    // it on the way in), so no normalization is needed here.
    return !READ_HTTP_METHOD_SET.has(context.method);
  }
  const { action_type } = parseActionResource(context.resource);
  return !READ_ACTION_TYPE_SET.has(action_type);
}

/**
 * Build a connection-level policy that covers both HTTP and action access.
 *
 * Always produces three statements:
 * 1. `can_use` for the authentication
 * 2. `can_execute` on `http` scoped by connection_id (+ method filter for read)
 * 3. `can_execute` on `action/{selectedApi}/{action_type}/*` per allowed type,
 *    scoped by connection_id. For read access, the resource list expands to
 *    one entry per read action_type so the engine matches via the resource
 *    string rather than a separate `path: ["action_type"]` condition.
 */
export function buildConnectionPolicy(options: {
  connectionId: string;
  selectedApi: string;
  accessLevel: AccessLevel;
}): Policy {
  const { connectionId, selectedApi, accessLevel } = options;

  const authStatement: Statement = {
    effect: "allow",
    permissions: ["can_use"],
    resources: [`connection/${connectionId}`],
    conditions: [],
  };

  const connectionCondition: Condition = {
    path: ["connection_id"],
    operator: "equals",
    value: connectionId,
  };

  const httpConditions: Condition[] = [connectionCondition];
  if (accessLevel === "read") {
    httpConditions.push({
      path: ["method"],
      operator: "in",
      value: [...READ_HTTP_METHODS],
    });
  }

  const httpStatement: Statement = {
    effect: "allow",
    permissions: ["can_execute"],
    resources: ["http"],
    conditions: httpConditions,
  };

  const apiPattern = globSelectedApiVersion(selectedApi);
  const actionResources =
    accessLevel === "read"
      ? READ_ACTION_TYPES.map((t) => `action/${apiPattern}/${t}/*`)
      : [`action/${apiPattern}/*/*`];

  const actionStatement: Statement = {
    effect: "allow",
    permissions: ["can_execute"],
    resources: actionResources,
    conditions: [connectionCondition],
  };

  return {
    version: 2,
    statements: [authStatement, httpStatement, actionStatement],
  };
}
