// ABOUTME: Canonical request context types shared between sdkapi and approvalsapi.
// ABOUTME: These define the contract for how requests are described in approval flows and policy evaluation.

import { z } from "zod";
import { extendZodWithOpenApi } from "@asteasolutions/zod-to-openapi";

extendZodWithOpenApi(z);

/**
 * Parsed URL components for policy evaluation.
 * Matches the ParsedUrl shape from @zapier/policy-schema so that
 * evaluatePolicy condition paths like ["url", "host"] resolve correctly.
 */
export const ParsedUrlSchema = z
  .object({
    scheme: z.string().openapi({ description: 'URL scheme, e.g. "https"' }),
    host: z.string().openapi({ description: 'Hostname, e.g. "api.example.com"' }),
    port: z
      .number()
      .int()
      .openapi({
        description: "Port number (defaults to 443 for https, 80 for http)",
      }),
    path: z.string().openapi({ description: 'URL path, e.g. "/v1/foo"' }),
    query: z
      .record(z.string(), z.array(z.string()))
      .openapi({
        description: "Query parameters as key to string array mapping",
      }),
  })
  .openapi("ParsedUrl", {
    description: "Parsed URL components for policy condition matching",
  });
export type ParsedUrl = z.infer<typeof ParsedUrlSchema>;

/** Default ports by scheme, used when URL has no explicit port. */
export const DEFAULT_PORTS: Record<string, number> = {
  http: 80,
  https: 443,
};

/**
 * Parse a raw URL string into a ParsedUrl.
 * Same logic as parseUrlForPolicyContext in @zapier/policy.
 */
export function parseUrl(raw: string): ParsedUrl {
  const url = new URL(raw);
  const scheme = url.protocol.slice(0, -1).toLowerCase();
  const host = url.hostname.toLowerCase();
  const port = url.port ? parseInt(url.port, 10) : (DEFAULT_PORTS[scheme] ?? 0);
  const path = url.pathname || "/";
  const query: Record<string, string[]> = {};
  for (const [key, value] of url.searchParams) {
    if (!query[key]) {
      query[key] = [];
    }
    query[key].push(value);
  }
  return { scheme, host, port, path, query };
}

/**
 * Reconstruct a URL string from a ParsedUrl.
 * Same logic as buildUrl in @zapier/policy.
 */
export function buildUrlString(parsed: ParsedUrl): string {
  const { scheme, host, port, path, query } = parsed;
  const defaultPort = DEFAULT_PORTS[scheme];
  const portString = port !== defaultPort ? `:${String(port)}` : "";
  const params = new URLSearchParams();
  for (const [key, values] of Object.entries(query)) {
    for (const value of values) {
      params.append(key, value);
    }
  }
  const queryString = params.toString();
  return `${scheme}://${host}${portString}${path}${queryString ? "?" + queryString : ""}`;
}

/**
 * HTTP request context for approval/policy flows.
 * Sent by sdkapi when a relay request is denied, stored by approvalsapi,
 * and used for both policy evaluation and building policy conditions.
 *
 * The url field is a ParsedUrl object (matching @zapier/policy-schema's ParsedUrl)
 * so that evaluatePolicy conditions like ["url", "host"] resolve correctly.
 */
export const HttpRequestContextSchema = z
  .object({
    request_type: z
      .literal("http_request")
      .openapi({ description: "Context type discriminator" }),
    method: z
      .string()
      .max(10)
      .transform((m) => m.toUpperCase())
      .openapi({ description: "HTTP method" }),
    /** Parsed URL components for policy condition matching */
    url: ParsedUrlSchema,
    /** Filtered headers (IGNORED_HEADERS excluded, keys lowercased) */
    headers: z
      .record(z.string(), z.string())
      .openapi({
        description: "Filtered headers (IGNORED_HEADERS excluded, keys lowercased)",
      }),
    /** Raw body string */
    body: z
      .string()
      .max(65536)
      .nullable()
      .openapi({ description: "Raw body string" }),
    /**
     * Parsed JSON body. Authored as `z.unknown().pipe(z.json())` so
     * zod-to-openapi sees the outer `z.unknown()` and emits a permissive
     * field (no recursive `$ref`, no type), while the inner `z.json()`
     * still rejects non-JSON values (`Date`, `undefined`, functions) at
     * parse time. Same inferred `JsonValue` type either way.
     */
    body_json: z
      .unknown()
      .pipe(z.json())
      .nullable()
      .describe("Parsed JSON body (if applicable)"),
    /** Zapier connection ID used for this request */
    connection_id: z
      .string()
      .max(255)
      .optional()
      .openapi({ description: "Zapier connection ID used for this request" }),
    /** Optional human-readable reason for the request */
    reason: z
      .string()
      .max(1024)
      .optional()
      .openapi({ description: "Optional human-readable reason for the request" }),
  })
  .openapi("HttpRequestContext");
export type HttpRequestContext = z.infer<typeof HttpRequestContextSchema>;

/**
 * Canonical Zapier action types.
 *
 * Mirrors the `action_type` enum in sdkapi's OpenAPI spec
 * (`packages/openapi-spec/openapi.d.ts` `action_type`). Single source of
 * truth for any code that branches on or filters by action_type — keeps
 * `ActionRunContextSchema`, `BuildActionRunContextOptionsSchema`, and the
 * `READ_ACTION_TYPES` allowlist in `connection-policy.ts` aligned.
 */
export const ActionTypeSchema = z
  .enum([
    "filter",
    "read",
    "read_bulk",
    "run",
    "search",
    "search_and_write",
    "search_or_write",
    "write",
  ])
  .openapi("action_type", { description: "Canonical Zapier action type." });
export type ActionType = z.infer<typeof ActionTypeSchema>;

/**
 * Allowed character set for the `selected_api` segment of an action
 * resource. Blocks `*`, `/`, `:`, whitespace, and other glob/path
 * metacharacters that would otherwise widen policy scope. Permits at
 * most one `@`, which `globSelectedApiVersion` treats as the
 * version separator.
 */
export const ACTION_RESOURCE_SEGMENT_PATTERN =
  /^[A-Za-z0-9._+-]+(?:@[A-Za-z0-9._+-]+)?$/;

/**
 * Allowed character set for the `action_key` segment of an action
 * resource. More permissive than `ACTION_RESOURCE_SEGMENT_PATTERN`
 * because sdkapi emits keys like `ae:358405` and `core:123abc` that
 * carry a namespace prefix separated by `:`. Still blocks `*`, `/`,
 * whitespace, and other glob/path metacharacters.
 */
export const ACTION_KEY_SEGMENT_PATTERN =
  /^[A-Za-z0-9._+:-]+(?:@[A-Za-z0-9._+:-]+)?$/;

/**
 * Parse an action resource string of the form
 * `action/{selected_api}/{action_type}/{action_key}` into its parts.
 * Throws if the string doesn't match the canonical 4-segment shape or
 * if its `action_type` segment isn't one of the canonical 8 — every
 * action_run context that has been through `ActionRunContextSchema` is
 * guaranteed to parse cleanly, so a thrown error here means upstream
 * validation was bypassed.
 */
export function parseActionResource(resource: string): {
  selected_api: string;
  action_type: ActionType;
  action_key: string;
} {
  const segments = resource.split("/");
  if (segments.length !== 4 || segments[0] !== "action") {
    throw new Error(
      `action resource must be action/{selected_api}/{action_type}/{action_key}: got ${resource}`,
    );
  }
  const [, selectedApi, actionTypeRaw, actionKey] = segments;
  if (!selectedApi || !actionTypeRaw || !actionKey) {
    throw new Error(`action resource has empty segment: ${resource}`);
  }
  const actionType = ActionTypeSchema.safeParse(actionTypeRaw);
  if (!actionType.success) {
    throw new Error(
      `action resource has unknown action_type "${actionTypeRaw}": ${resource}`,
    );
  }
  if (!ACTION_RESOURCE_SEGMENT_PATTERN.test(selectedApi)) {
    throw new Error(
      `action resource has invalid selected_api segment "${selectedApi}": ${resource}`,
    );
  }
  if (!ACTION_KEY_SEGMENT_PATTERN.test(actionKey)) {
    throw new Error(
      `action resource has invalid action_key segment "${actionKey}": ${resource}`,
    );
  }
  return {
    selected_api: selectedApi,
    action_type: actionType.data,
    action_key: actionKey,
  };
}

/**
 * Raw input shape for `ActionRunContextSchema`, before the transform that
 * canonicalizes legacy fields into `resource`. Exposed for the OpenAPI
 * schema generator (which can't represent transforms) — runtime callers
 * should use `ActionRunContextSchema`, which accepts either the canonical
 * `resource` field or the legacy `{selected_api, action_type, action_key}`
 * triple on input.
 */
export const ActionRunContextInputSchema = z
  .object({
    request_type: z
      .literal("action_run")
      .openapi({ description: "Context type discriminator" }),
    resource: z
      .string()
      .max(1024)
      .optional()
      .openapi({
        description:
          "Canonical action resource, e.g. action/Slack@1.0.0/write/send_message",
      }),
    selected_api: z
      .string()
      .max(255)
      .optional()
      .openapi({
        deprecated: true,
        description:
          "Legacy: app identifier, e.g. Slack@1.0.0. Prefer `resource`.",
      }),
    action_type: ActionTypeSchema.optional().openapi({
      deprecated: true,
      description: "Legacy: canonical Zapier action type. Prefer `resource`.",
    }),
    action_key: z
      .string()
      .max(255)
      .optional()
      .openapi({
        deprecated: true,
        description:
          "Legacy: action key, e.g. send_message. Prefer `resource`.",
      }),
    connection_id: z
      .string()
      .max(255)
      .optional()
      .openapi({ description: "Zapier connection ID used for this request" }),
    /** Action input parameters. See body_json above for the pipe rationale. */
    inputs: z
      .unknown()
      .pipe(z.json())
      .optional()
      .describe("Action input parameters"),
    reason: z
      .string()
      .max(1024)
      .optional()
      .openapi({ description: "Optional human-readable reason for the request" }),
  })
  .openapi("ActionRunContext", {
    description:
      "Action run context. The canonical shape carries the action identity in a single `resource` field of the form `action/{selected_api}/{action_type}/{action_key}`. The legacy `{selected_api, action_type, action_key}` shape is also accepted on input during the migration window — approvalsapi normalizes it to the canonical form before storage.",
  });

export const ActionRunContextSchema = ActionRunContextInputSchema.transform(
  (input, ctx) => {
    const resource =
      input.resource ??
      (input.selected_api && input.action_type && input.action_key
        ? `action/${input.selected_api}/${input.action_type}/${input.action_key}`
        : undefined);
    if (resource === undefined) {
      ctx.addIssue({
        code: "custom",
        message:
          "action_run context requires either `resource` or all of `selected_api`/`action_type`/`action_key`",
      });
      return z.NEVER;
    }
    try {
      parseActionResource(resource);
    } catch (err) {
      ctx.addIssue({
        code: "custom",
        message: err instanceof Error ? err.message : String(err),
      });
      return z.NEVER;
    }
    return {
      request_type: "action_run" as const,
      resource,
      ...(input.connection_id !== undefined && {
        connection_id: input.connection_id,
      }),
      ...(input.inputs !== undefined && { inputs: input.inputs }),
      ...(input.reason !== undefined && { reason: input.reason }),
    };
  },
);
export type ActionRunContext = z.infer<typeof ActionRunContextSchema>;

/**
 * Union of all request context types, keyed on `request_type`.
 *
 * Plain `z.union` (not `z.discriminatedUnion`) because
 * `ActionRunContextSchema` carries a `.transform` and discriminated
 * unions can't accept a `ZodEffects` member. The discriminator metadata
 * below tells OpenAPI consumers how to narrow the union — zod-to-openapi
 * emits this as `anyOf` + discriminator, which openapi-typescript and
 * other codegen targets render as a properly narrowed TS union.
 */
export const RequestContextSchema = z
  .union([HttpRequestContextSchema, ActionRunContextSchema])
  .openapi("RequestContext", {
    description: "Union of request context shapes, keyed on `request_type`.",
    discriminator: {
      propertyName: "request_type",
      mapping: {
        http_request: "#/components/schemas/HttpRequestContext",
        action_run: "#/components/schemas/ActionRunContext",
      },
    },
  });
export type RequestContext = z.infer<typeof RequestContextSchema>;
