// ABOUTME: Assembles complete Policy objects from request contexts.
// ABOUTME: Single source of truth for "exact request" instant policies used by web UI and API.

import type { Policy, Statement } from "@zapier/policy-schema";
import type {
  RequestContext,
  HttpRequestContext,
  ActionRunContext,
} from "./types.ts";
import {
  buildExactHttpConditions,
  buildExactActionConditions,
} from "./conditions.ts";

/**
 * Build a `can_use` authentication statement, if the context has a connection_id.
 */
function buildAuthStatement(authenticationId: string): Statement {
  return {
    effect: "allow",
    permissions: ["can_use"],
    resources: [`connection/${authenticationId}`],
    conditions: [],
  };
}

/**
 * Build an exact-match policy from an HTTP request context.
 *
 * Produces a policy that allows only the specific request described by the context:
 * - `can_use` statement for the authentication (if present)
 * - `can_execute` statement for `http` with conditions from `buildExactHttpConditions`
 *   plus a `keys_in` guard restricting allowed query parameter keys
 */
function httpContextToPolicy(context: HttpRequestContext): Policy {
  const statements: Statement[] = [];

  if (context.connection_id) {
    statements.push(buildAuthStatement(context.connection_id));
  }

  const conditions = buildExactHttpConditions(context);

  // Add a keys_in guard so only the query param keys present in the original
  // request are allowed — blocks injection of extra query params.
  conditions.push({
    path: ["url", "query"],
    operator: "keys_in",
    value: Object.keys(context.url.query),
  });

  statements.push({
    effect: "allow",
    permissions: ["can_execute"],
    resources: ["http"],
    conditions,
  });

  return { version: 2, statements };
}

/**
 * Build an exact-match policy from an action run context.
 *
 * Produces a policy that allows only the specific action described by the context:
 * - `can_use` statement for the authentication (if present)
 * - `can_execute` statement for the action resource with input conditions
 */
function actionContextToPolicy(context: ActionRunContext): Policy {
  const statements: Statement[] = [];

  if (context.connection_id) {
    statements.push(buildAuthStatement(context.connection_id));
  }

  statements.push({
    effect: "allow",
    permissions: ["can_execute"],
    resources: [context.resource],
    conditions: buildExactActionConditions(context),
  });

  return { version: 2, statements };
}

/**
 * Build an exact-match policy from any supported request context.
 *
 * This is the single source of truth for "allow this exact request" instant policies.
 * Used by the web UI and anywhere else that needs to produce an exact policy from a context.
 */
export function toExactPolicy(context: RequestContext): Policy {
  if (context.request_type === "http_request") {
    return httpContextToPolicy(context);
  }
  return actionContextToPolicy(context);
}
