// ABOUTME: Canonical builders for creating request contexts from raw request parts.
// ABOUTME: Used by sdkapi to build both approval contexts and policy eval contexts.

import { z } from "zod";
import {
  HttpRequestContextSchema,
  ActionRunContextSchema,
  ActionTypeSchema,
  parseUrl,
  ACTION_RESOURCE_SEGMENT_PATTERN,
  ACTION_KEY_SEGMENT_PATTERN,
  type HttpRequestContext,
  type ActionRunContext,
} from "./types.ts";
import { buildActionResource } from "./conditions.ts";
import { IGNORED_HEADERS } from "./constants.ts";

export const BuildHttpRequestContextOptionsSchema = z.object({
  method: z.string(),
  /** Raw URL string. Will be normalized with https:// if no protocol present. */
  url: z.string(),
  /** Raw headers from the request. Will be filtered through IGNORED_HEADERS. */
  headers: z
    .record(
      z.string(),
      z.union([z.string(), z.array(z.string()), z.undefined()]),
    )
    .optional(),
  /** Raw body string */
  body: z.string().nullable().optional(),
  /** Pre-parsed JSON body (e.g. from Fastify's automatic JSON parsing) */
  body_json: z.json().optional(),
  /** Connection ID associated with this request */
  connection_id: z.string().optional(),
});
export type BuildHttpRequestContextOptions = z.infer<
  typeof BuildHttpRequestContextOptionsSchema
>;

/**
 * Build a canonical HttpRequestContext from raw request parts.
 *
 * This is the single source of truth for how HTTP request contexts are created.
 * Both sdkapi (for policy evaluation) and approvalsapi (for context storage)
 * should use this to ensure the context shape is consistent.
 *
 * Matches the behavior of createPolicyHttpRequest from @zapier/policy, with
 * the addition of header filtering through IGNORED_HEADERS.
 *
 * - Normalizes URL (adds https:// if missing) and parses into { scheme, host, port, path, query }
 * - Filters headers through IGNORED_HEADERS, lowercases keys, string values only
 * - Auto-parses body_json from body when content-type is JSON and body_json not provided
 * - body defaults to null (not undefined)
 */
export function buildHttpRequestContext(
  options: BuildHttpRequestContextOptions,
): HttpRequestContext {
  // Validate options up-front so downstream string ops (e.g. method.toUpperCase)
  // see well-typed values. Mirrors the pattern in buildActionRunContext.
  const parsed = BuildHttpRequestContextOptionsSchema.parse(options);

  // Normalize URL — SDK CLI strips the protocol
  const rawUrl = parsed.url.includes("://")
    ? parsed.url
    : `https://${parsed.url}`;
  const url = parseUrl(rawUrl);

  // Filter headers: exclude ignored, lowercase keys, string values only
  const headers: Record<string, string> = {};
  if (parsed.headers) {
    for (const [key, value] of Object.entries(parsed.headers)) {
      const lowerKey = key.toLowerCase();
      if (!IGNORED_HEADERS.has(lowerKey) && typeof value === "string") {
        headers[lowerKey] = value;
      }
    }
  }

  // Auto-parse body_json from body when content-type is JSON
  // (matches createPolicyHttpRequest behavior from @zapier/policy)
  let body_json: unknown = null;
  if (parsed.body_json !== undefined) {
    body_json = parsed.body_json;
  } else if (parsed.body) {
    const contentType = headers["content-type"];
    const isJson =
      typeof contentType === "string" &&
      (contentType.includes("application/json") ||
        (contentType.includes("application/") &&
          contentType.includes("+json")));
    if (isJson) {
      try {
        body_json = JSON.parse(parsed.body);
      } catch {
        // Invalid JSON body — leave body_json as null
      }
    }
  }

  return HttpRequestContextSchema.parse({
    request_type: "http_request",
    method: parsed.method.toUpperCase(),
    url,
    headers,
    body: parsed.body ?? null,
    body_json,
    connection_id: parsed.connection_id,
  });
}

export const BuildActionRunContextOptionsSchema = z.object({
  selected_api: z.string().regex(ACTION_RESOURCE_SEGMENT_PATTERN, {
    message:
      "selected_api must contain only [A-Za-z0-9._@+-] (no globs, slashes, or whitespace)",
  }),
  action_type: ActionTypeSchema,
  action_key: z.string().regex(ACTION_KEY_SEGMENT_PATTERN, {
    message:
      "action_key must contain only [A-Za-z0-9._@:+-] (no globs, slashes, or whitespace)",
  }),
  connection_id: z.string().optional(),
  inputs: z.json().optional(),
  reason: z.string().optional(),
});
export type BuildActionRunContextOptions = z.infer<
  typeof BuildActionRunContextOptionsSchema
>;

/**
 * Build a canonical ActionRunContext from raw action parts.
 *
 * Callers pass the three identity fields separately for readability;
 * this validates them and collapses them into the canonical `resource`
 * string the schema stores.
 */
export function buildActionRunContext(
  options: BuildActionRunContextOptions,
): ActionRunContext {
  const parsed = BuildActionRunContextOptionsSchema.parse(options);
  return ActionRunContextSchema.parse({
    request_type: "action_run",
    resource: buildActionResource({
      selected_api: parsed.selected_api,
      action_type: parsed.action_type,
      action_key: parsed.action_key,
    }),
    connection_id: parsed.connection_id,
    inputs: parsed.inputs,
    reason: parsed.reason,
  });
}
