// ABOUTME: Canonical set of headers to exclude when building request contexts.
// ABOUTME: Shared between sdkapi (context creation) and approvalsapi (condition building).

/**
 * Headers to exclude when building request contexts from raw HTTP requests.
 *
 * These are either sensitive (auth credentials), HTTP infrastructure headers
 * that vary per-request, or proxy-internal headers that are not meaningful
 * for policy decisions.
 */
export const IGNORED_HEADERS = new Set([
  // Auth / credentials — never include in contexts or policy conditions
  "authorization",
  "x-relay-authorization",
  "x-relay-authentication-id",
  "x-api-key",
  "cookie",
  "set-cookie",
  "proxy-authorization",

  // HTTP infrastructure — varies per-request, not policy-relevant
  "host",
  "connection",
  "content-length",
  "transfer-encoding",
  "accept-encoding",
  "user-agent",
  "accept",
  "accept-language",
  "sec-fetch-mode",

  // Proxy / forwarding — infrastructure, not meaningful for policy
  "x-forwarded-for",
  "x-forwarded-host",
  "x-forwarded-proto",
  "x-real-ip",

  // Proxy internal — sdkapi-specific headers
  "x-is-interactive-session",
  "x-relay-callback-url",
]);
